import{_ as p,c as e,o as l,af as i}from"./chunks/framework.BKeRpnBD.js";const u=JSON.parse('{"title":"63、【既济】 离下坎上","description":"周易集注 - 63、【既济】 离下坎上","frontmatter":{"title":"63、【既济】 离下坎上","description":"周易集注 - 63、【既济】 离下坎上"},"headers":[],"relativePath":"zh/classics/jizhu/067.md","filePath":"zh/classics/jizhu/067.md"}'),r={name:"zh/classics/jizhu/067.md"};function h(t,a,s,n,c,d){return l(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="_63、【既济】-离下坎上" tabindex="-1">63、【既济】 离下坎上 <a class="header-anchor" href="#_63、【既济】-离下坎上" aria-label="Permalink to “63、【既济】 离下坎上”">​</a></h1><p>既济者，事之已成也。为卦水火相交，各得其用，又六爻之位，各得其位，故为既济。《序卦》：有过物者必济，故受之以既济，所以次小过。</p><p>亨小者，言不如方济之时亨通之盛大也。譬如*日之既昃，不如日中之盛，所以亨小而不能大也。利贞者，即泰之艰贞也。日中则昃，月盈则食，无平不陂，无往不复，一治一乱，乃理数之常。方济之时，人心儆戒，固无不吉矣。及既济之后，人心恃其既济，般乐怠敖，未有不乱者。此虽气数之使然，亦人事之必然也，故利于贞。</p><ul><li>原文“譬如”误作“喜如”，此依他本修正。</li></ul><p>《彖》曰：既济亨小者，亨也。利贞，刚柔正而位当也。初吉，柔得中也。终止则乱，其道穷也。</p><p>释卦名亨小义，又以卦体释卦辞，言既济亨小者，非不亨也，正当亨通之时也。但济曰既，则亨小，不如方济之时，亨通之盛大矣，故曰既济，亨小者，亨也。非不亨也，特小耳。小字生于既字，初三五阳居阳位，二四六阴居阴位，刚柔正而位当也。刚柔正即是位当，有贞之义，故曰利贞。初指六二，二居内卦，方济之初，而能柔顺得中，则思患深而豫防密，所以吉也。终止则乱者，人之常情。处平常无事之时，则止心生，止则心有所怠而不复进，乱之所由起也。处艰难多事之时，则戒心生，戒则心有所畏，而不敢肆，此治之所由兴也，可见非终之为乱也，于其终而有止心，此乱之所由生也。不止，乱安从生?文王曰终乱，孔子曰终止则乱，圣人赞易之旨深矣。其道穷者，以人事言。怠胜敬则凶，此人道之理穷也。以天运言之，盛极则必衰，此天道之数穷也。以卦体言之，水在上，终必润下，火在下，终必炎上，此卦体以势穷也。今当既济之后，止心既生，岂不终乱?故曰其道穷。</p><h3 id="《象》曰-水在火上-既济-君子以思患而豫防之。" tabindex="-1">《象》曰：水在火上，既济，君子以思患而豫防之。 <a class="header-anchor" href="#《象》曰-水在火上-既济-君子以思患而豫防之。" aria-label="Permalink to “《象》曰：水在火上，既济，君子以思患而豫防之。”">​</a></h3><p>患者蹇难之事，象坎险;防者见几之事，象离明。思以心言，豫以事言。思患者虑乎其后，豫防者图之于先。能如此，则未雨而彻桑土，未火而徙积薪。天下之事，莫不皆然，非但既济当如此也。</p><p>初九，曳其轮，濡其尾，无咎。</p><p>坎为轮，为狐，为曳轮，狐曳之象也。初在狐后，尾象。在水之下，濡象。若专以初论，轮在下，尾在后，皆初之象。濡其尾者，垂其尾于后，而霑濡其水也。舆赖轮以行，曳其轮则不前。兽必揭其尾而后涉，濡其尾则不济，皆不轻举妄动之象也。无咎者，能保其既济也。</p><p>九当既济之时，尚在既济之初，可以谨戒而守成者。然初刚得其正，不轻于动，故有曳轮濡尾之象。以此守成，无咎之道，故其象占如此。</p><h3 id="《象》曰-曳其轮-义无咎也。" tabindex="-1">《象》曰：曳其轮，义无咎也。 <a class="header-anchor" href="#《象》曰-曳其轮-义无咎也。" aria-label="Permalink to “《象》曰：曳其轮，义无咎也。”">​</a></h3><p>以此守成，理当无咎。</p><p>六二，妇丧其笰*，勿逐，七日得。</p><p>二乃阴爻，离为中女，妇之象也。又应爻中男，乃五之妇也。笰者车后笰也，即今舟中蓬之类，所以从竹。坎为舆，离中虚，笰之象也。近日书房皆写茀，茀者草多也，去笰远矣。坎为盗*，离持戈兵，丧笰之象也。此与屯卦六二相同，屯乘刚，故邅如班如，此则乘承皆刚，故丧其笰矣。妇人丧其笰，则无遮蔽，不能行矣。变乾居一，前坎居六，离为日，七日之象也。勿逐自得者，六二中正，久则妄求去，正应合，所以勿逐自得也。又详见睽卦初九。若以理数论，阴阳极于六，七则变矣，时变则自得，盖变则通之意。</p><p>二以中正之德，而上应中正之君，本五之妇也。但乘承皆刚，与五不得相合，故有妇丧笰，不能行之象。然上下中正，岂有不得相合之理，但俟其时耳。故又戒占者，勿可追逐，宜令其自得也，又有此象。</p><ul><li>通行本《经文》作“茀”。</li></ul><p>通行本《经文》作“茀”。</p><ul><li>原文误作“离为盗”，依他本修正。</li></ul><p>原文误作“离为盗”，依他本修正。</p><h3 id="《象》曰-七日得-以中道也。" tabindex="-1">《象》曰：七日得，以中道也。 <a class="header-anchor" href="#《象》曰-七日得-以中道也。" aria-label="Permalink to “《象》曰：七日得，以中道也。”">​</a></h3><p>中道者居下卦之中，此六二之德也。济世之具在我，故不求自得。</p><p>九三，高宗伐鬼方，三年克之，小人勿用。</p><p>离为戈兵，变爻为震，戈兵震动，伐国之象也。鬼方者，北方国也，夏曰昆吾<em>，商曰鬼方，周曰猃狁，汉曰匈奴，魏曰鲜卑</em>，三与上六为应，坎居北*，故曰鬼方。坎为隐伏，鬼之象也。变坤，中爻为方，方之象也。周公非空取鬼方二字也。离居三，三年之象也。既变坤，阳大阴小，小之象也。三居人位，小人之象也。变坤，中爻成艮止，勿用之象也。周公爻象一字不空，此所以为圣人之笔也。</p><p>既济之时，天下无事矣。三以刚居刚，故有伐国之象。然险陷在前，难以骤克，故又有三年方克之象。夫以高宗之贤，其用兵之难如此，而况既济无事之世。任用小人，舍内治而幸边功，未免穷兵厉民矣。故既言用兵之难，不可轻动，而又言任人不可不审也。教占者处既济之时当如此，戒之深矣。</p><ul><li>“昆吾”慈恩本作“獯鬻”。</li></ul><p>“昆吾”慈恩本作“獯鬻”。</p><ul><li>“鲜卑”慈恩本作“突厥”。</li></ul><p>“鲜卑”慈恩本作“突厥”。</p><ul><li>“北”原文误作“比”，依慈恩本修正。</li></ul><p>“北”原文误作“比”，依慈恩本修正。</p><h3 id="《象》曰-三年克之-惫也。惫蒲败反" tabindex="-1">《象》曰：三年克之，惫也。惫蒲败反 <a class="header-anchor" href="#《象》曰-三年克之-惫也。惫蒲败反" aria-label="Permalink to “《象》曰：三年克之，惫也。惫蒲败反”">​</a></h3><p>惫者病也，时久师老，财匮力困也。甚言兵不可轻用。</p><p>六四，繻有，衣袽，终日戒。</p><p>细密之罗曰繻，凡帛皆可言，故过关之帛曰繻。袽者蔽衣也。四变，中爻为干，衣之象也，错坤为帛，繻之象也，又成兑为毁折，敝衣之象也。成卦为既济，本爻又得位，犹人服饰之盛也。济道将革，不敢恃其服饰之盛，虽有繻不衣之，而乃衣其敝衣也。终日，尽日也，居离日之上，离日已尽之象也。戒者戒惧不安也，四多惧，戒之象也。衣袽以在外言，终日戒以心言。</p><p>六四当出离入坎之时，阴柔得正，知济道将革，坎陷临前有所疑惧，故有有繻不衣，乃衣其袽，终日戒惧之象。占者必如是，方可保既济也。</p><h3 id="《象》曰-终日戒-有所疑也。" tabindex="-1">《象》曰：终日戒，有所疑也。 <a class="header-anchor" href="#《象》曰-终日戒-有所疑也。" aria-label="Permalink to “《象》曰：终日戒，有所疑也。”">​</a></h3><p>疑者，疑祸患之将至也。</p><p>九五，东邻杀牛，不如西邻之禴祭，实受其福。</p><p>邻者，文王圆图离居正南，坎居正北，震居正东，兑居正西，则东西者，乃水火之邻也，故有东西之象。观震卦，上六变离，爻辞曰，不于其躬，于其邻，则震兑又以南北为邻矣。杀牛不禴祭者，言当既济之终，不当侈盛，当损约也。五变坤，牛之象。离为戈兵，坎为血，见戈兵而流血，杀之象。禴祭夏，离为夏，禴之象。坎为隐伏，人鬼之象。又为有孚，诚心祭人鬼之象。杀牛，盛祭，禴薄祭，实受其福者，阳实阴虚，阳大阴小，《小象》曰，吉大来也，大字即实字，吉字即福字，大与实皆指五也。言如此损约则五吉而受其福矣。泰入否圣人曰“勿恤其孚，于食有福”，既济将终圣人曰“不如禴祭，实受其福”，圣人之情见矣。六四不衣美衣而衣恶衣，九五*不尚盛祭，而尚薄祭，皆善与处终乱者也。</p><p>五居尊位，当既济之终，正终乱之时，故圣人戒占者曰济将终矣，与其侈盛，不如艰难菲薄，以亨既济之福，若侈盛则止而乱矣。故其戒之之象如此。</p><ul><li>“九五”原文误作“九二”，依慈恩本修正。</li></ul><h3 id="《象》曰-东邻杀牛-不如西邻之时也-实受其福-吉大来也。" tabindex="-1">《象》曰：东邻杀牛，不如西邻之时也，实受其福，吉大来也。 <a class="header-anchor" href="#《象》曰-东邻杀牛-不如西邻之时也-实受其福-吉大来也。" aria-label="Permalink to “《象》曰：东邻杀牛，不如西邻之时也，实受其福，吉大来也。”">​</a></h3><p>之当作知，因与音同，写时之误。时[即]*二簋应有时之时，言东邻杀牛，不如西邻知时也。盖济道终乱之时，此何时哉。能知其时，艰难菲薄以处之，则自有以享其既济之福矣。吉大来者，言吉来于大也。来字与益卦自外来也来字同。</p><ul><li>慈恩本有“即”字。</li></ul><p>上六，濡其首，厉。</p><p>初九卦之始，故言濡尾者，心有所畏惧，而不敢遽涉也。上六卦之终，故言濡首者，志已盈满，而惟知其涉也。大过上六，泽水之深矣，故灭顶。既济上六，坎水之深矣，故濡首。</p><p>既济之极，正终乱之时也，故有狐涉水，而濡首之象。既濡其首，已溺其身，占者如是，危可知矣。</p><h3 id="《象》曰-濡其首厉-何可久也。" tabindex="-1">《象》曰：濡其首厉，何可久也。 <a class="header-anchor" href="#《象》曰-濡其首厉-何可久也。" aria-label="Permalink to “《象》曰：濡其首厉，何可久也。”">​</a></h3><p>言必死亡。</p>',50)])])}const _=p(r,[["render",h]]);export{u as __pageData,_ as default};
